def echantillonner(df, n):
    """Sous-échantillon aléatoire reproductible (n=None : tout le jeu)."""
    if n is None or n >= len(df):
        return df.reset_index(drop=True)
    return df.sample(n=n, random_state=GRAINE).reset_index(drop=True)


