@torch.no_grad()
def logits_encodeur(modele, textes, lot=64):
    return np.concatenate([modele(**encoder(textes[i:i + lot]).to(DEVICE)).logits.float().cpu().numpy()
                           for i in range(0, len(textes), lot)])


def temperature_optimale(logits, y):
    """Calibration par température (Guo et al., 2017) : T unique minimisant la NLL de validation."""
    def nll(T):
        return -np.mean(np.log(softmax(logits / T)[np.arange(len(y)), y] + 1e-12))
    return float(minimize_scalar(nll, bounds=(0.05, 20.0), method="bounded").x)


@torch.no_grad()
def latences_encodeur(modele, textes):
    """Latence par message (lot de 1), comparable à celle du LLM."""
    durees = []
    for texte in textes:
        with chrono(durees):
            modele(**encoder([texte]).to(DEVICE)).logits.argmax(-1).item()
    return durees


