import os
from concurrent.futures import ThreadPoolExecutor

APPELS_PARALLELES = 4
CONSIGNE_CONFIANCE = "\n\nDonne aussi ta confiance, entre 0 et 1, que cette option soit la bonne."


class DecideurService:
    """Phase banque : même prompt, service LLM interne (convention OpenAI). Log-probabilités du premier jeton
    si le service les expose (équivalent des logits) ; sinon JSON {option, confiance} (confiance verbalisée)."""

    def __init__(self, prefixe="LLMAAS"):
        self.prefixe, self.client = prefixe, client_openai(prefixe)
        self.modele = os.environ.get(f"{prefixe}_MODEL")
        sonde = [{"role": "user", "content": contenu_utilisateur(
            GROUPES[NIVEAU_1], PERMUTATIONS[NIVEAU_1][0], "Bonjour, j'ai une question.")}]
        self.logprobs = self._par_logprobs(sonde, len(GROUPES[NIVEAU_1])) is not None
        self.mode = "service : log-probabilités" if self.logprobs else "service : confiance verbalisée"
        print("Lecture des probabilités :", self.mode)

    def _par_logprobs(self, messages, k):
        try:
            reponse = self.client.chat.completions.create(
                model=self.modele, messages=messages, max_tokens=1, temperature=0.0, logprobs=True, top_logprobs=20)
            candidats = reponse.choices[0].logprobs.content[0].top_logprobs
        except Exception:
            return None
        position = {l: j for j, l in enumerate(LETTRES[:k])}
        z = np.full(k, -np.inf)
        for c in candidats:  # « A » et « ␣A » sont cumulés
            j = position.get(c.token.strip())
            if j is not None:
                z[j] = np.logaddexp(z[j], c.logprob)
        if not np.isfinite(z).any():
            return None
        q = np.exp(z - z.max())
        return q / q.sum()

    def _par_schema(self, messages, k):
        schema = {"type": "object", "additionalProperties": False, "required": ["option", "confiance"],
                  "properties": {"option": {"type": "string", "enum": LETTRES[:k]}, "confiance": {"type": "number"}}}
        try:
            sortie = llm_chat([{"role": "user", "content": messages[0]["content"] + CONSIGNE_CONFIANCE}],
                              schema=schema, max_tokens=64, prefixe=self.prefixe)
            j, c = LETTRES[:k].index(sortie["option"]), float(sortie["confiance"])
        except Exception:
            return None
        c = min(max(c, 1.0 / k), 1.0)
        q = np.full(k, (1.0 - c) / (k - 1))
        q[j] = c
        return q

    def distribution(self, groupe, p, textes):
        options, permutation = GROUPES[groupe], PERMUTATIONS[groupe][p]
        lire = self._par_logprobs if self.logprobs else self._par_schema

        def un_message(texte):
            debut = time.perf_counter()
            q = lire([{"role": "user", "content": contenu_utilisateur(options, permutation, texte)}], len(options))
            return q, (time.perf_counter() - debut) * 1000

        with ThreadPoolExecutor(max_workers=APPELS_PARALLELES) as pool:
            sorties = list(pool.map(un_message, textes))
        P = np.full((len(textes), len(options)), 1.0 / len(options))
        for i, (q, _) in enumerate(sorties):
            if q is not None:
                P[i, permutation] = q
        lisible = np.array([q is not None for q, _ in sorties])
        return P, lisible, np.array([ms for _, ms in sorties])

from sklearn.metrics import f1_score


def macro_f1(y, p):
    return float(f1_score(y, p, labels=np.unique(y), average="macro", zero_division=0))


def exactitude(y, p):
    return float(np.mean(np.asarray(y) == np.asarray(p)))


def ece(correct, conf, n_intervalles=15):
    correct, conf = np.asarray(correct, float), np.clip(np.asarray(conf, float), 0.0, 1.0)
    case = np.minimum((conf * n_intervalles).astype(int), n_intervalles - 1)
    return float(sum(np.mean(case == b) * abs(correct[case == b].mean() - conf[case == b].mean())
                     for b in range(n_intervalles) if np.any(case == b)))


def brier(P, y):
    return float(np.mean(np.sum((P - np.eye(P.shape[1])[y]) ** 2, axis=1)))


def seuil_precision(conf_val, correct_val, cible=0.95):
    """Plus petit seuil tel que la précision des cas acceptés en validation atteigne la cible (inf si jamais)."""
    ordre = np.argsort(-conf_val, kind="stable")
    precision = np.cumsum(correct_val[ordre]) / np.arange(1, len(ordre) + 1)
    admissibles = np.where(precision >= cible)[0]
    return float(conf_val[ordre][admissibles.max()]) if len(admissibles) else np.inf


def latence_dict(durees):
    l = latences([float(x) for x in durees])
    valeurs = list(l.values()) if isinstance(l, dict) else list(l)
    p50, p95 = (l.get("p50", valeurs[0]), l.get("p95", valeurs[1])) if isinstance(l, dict) else valeurs[:2]
    return {"p50": float(p50), "p95": float(p95)}


def evaluer(P_brut, P_cal, conf_cal, pred, conf_val_cal, correct_val, accord, lisible):
    """Métriques communes aux deux approches ; rend (métriques, ic95, précision des cas acceptés)."""
    correct = pred == y_test
    pred_scen = np.where(pred >= 0, scen_classe[np.maximum(pred, 0)], -1)
    accepte = conf_cal >= seuil_precision(conf_val_cal, correct_val)
    metriques = {
        "macro_f1": macro_f1(y_test, pred), "exactitude": exactitude(y_test, pred),
        "exactitude_scenario": exactitude(scen_classe[y_test], pred_scen),
        "ece_brute": ece(correct, P_brut.max(1)), "ece": ece(correct, conf_cal), "brier": brier(P_cal, y_test),
        "accord_permutations": float(np.mean(accord)), "couverture_95": float(np.mean(accepte)),
        "taux_illisible": float(1.0 - np.mean(lisible))}
    ic = {"macro_f1": ic_bootstrap(y_test, pred, macro_f1, graine=GRAINE),
          "ece": ic_bootstrap(correct.astype(float), conf_cal, ece, graine=GRAINE)}
    ic95 = {k: [float(v[1]), float(v[2])] for k, v in ic.items()}
    precision_auto = float(correct[accepte].mean()) if accepte.any() else float("nan")
    return metriques, ic95, precision_auto
